"""Private decisions remain required at runtime, never generated by the build."""
import base64
import hashlib
from pathlib import Path
from tempfile import TemporaryDirectory
from unittest import TestCase
from unittest.mock import patch

from app import deployment, neon_transport, vercel_runtime as runtime


class PrivateBuildConfigurationTests(TestCase):
    def test_external_decisions_require_original_pins_and_hidden_values(self):
        values = {}
        with self.assertRaisesRegex(runtime.VercelBlocked, 'PRIVATE_ACCEPTANCE_MANIFEST_PINS_DIFFER'):
            runtime.prepare_acceptances(values, '.', {'private_runtime_configuration': 'external-acceptances-v1'})

    def test_valid_synthetic_private_input_is_separate_and_not_overwritten(self):
        a, b = b'SYNTHETIC FUNCTIONAL DECISION', b'SYNTHETIC TRANSPORT DECISION'
        pin_a, pin_b = hashlib.sha256(a).hexdigest(), hashlib.sha256(b).hexdigest()
        manifest = {'private_runtime_configuration': 'external-acceptances-v1',
                    'functional_acceptance_sha256': pin_a, 'transport_acceptance_sha256': pin_b}
        values = {'SIGRA_FUNCTIONAL_ACCEPTANCE_B64': base64.b64encode(a).decode(),
                  'SIGRA_NEON_TRANSPORT_ACCEPTANCE_B64': base64.b64encode(b).decode()}
        with TemporaryDirectory(dir=Path(__file__).parent) as directory:
            with patch.object(deployment, 'ACCEPTANCE_SHA256', pin_a), patch.object(neon_transport, 'ACCEPTANCE_SHA256', pin_b):
                runtime.prepare_acceptances(values, directory, manifest)
                self.assertEqual(Path(values['SIGRA_FUNCTIONAL_ACCEPTANCE_FILE']).read_bytes(), a)
                self.assertEqual(Path(values['SIGRA_NEON_TRANSPORT_ACCEPTANCE_FILE']).read_bytes(), b)
                with self.assertRaises(FileExistsError):
                    runtime.prepare_acceptances(values, directory, manifest)

    def test_changed_private_decision_fails_without_embedded_fallback(self):
        manifest = {'private_runtime_configuration': 'external-acceptances-v1',
                    'functional_acceptance_sha256': deployment.ACCEPTANCE_SHA256,
                    'transport_acceptance_sha256': neon_transport.ACCEPTANCE_SHA256}
        with TemporaryDirectory(dir=Path(__file__).parent) as directory:
            with self.assertRaisesRegex(runtime.VercelBlocked, 'PRIVATE_ACCEPTANCE_CONTENT_CHANGED'):
                runtime.prepare_acceptances({'SIGRA_FUNCTIONAL_ACCEPTANCE_B64': base64.b64encode(b'CHANGED').decode()}, directory, manifest)
            self.assertEqual(list(Path(directory).iterdir()), [])

    def test_legacy_mode_keeps_the_original_embedded_path(self):
        values = {}
        runtime.prepare_acceptances(values, '.', {})
        self.assertEqual(values['SIGRA_FUNCTIONAL_ACCEPTANCE_FILE'], str(runtime.ROOT / 'release/functional-acceptance.json'))

    def test_invalid_neon_external_path_does_not_read_embedded_file(self):
        with patch.dict('os.environ', {'SIGRA_NEON_TRANSPORT_ACCEPTANCE_FILE': '/not-a-real-ci-file'}):
            with self.assertRaisesRegex(deployment.DeploymentBlocked, 'NEON_TRANSPORT_ACCEPTANCE_UNREADABLE'):
                neon_transport.acceptance()
